# Generated by Phase: IMPLEMENT | Feature: EVOL-115, EVOL-082, EVOL-132
"""The design freeze: reliability planned up front (EVOL-115) and every critical decision bound to its law and gate
(EVOL-082, ADR-EVOL-082) — the design and the contracts the change touches, read at push, in CI and at BLUEPRINT --approve.

Every `docs/spec/*/design.md` and `contracts/openapi/**.{yaml,yml,json}` the change touches (the tree on disk against
the merge-base with the diff base) is read. Red when:

  (a) unanswered question  in `design.md § Reliability Questions`, a capability row weighted security, availability or
                           both has an RQ cell with no answer or no source (`answer · source`); a weight outside the
                           closed vocabulary (security, availability, both, none) is red. No section, no recognised
                           header or no weighted row → that design is `n/a` with its reason, never an ok note.
  (b) no outage response   an OpenAPI operation declares no response keyed `contracts.outage_status`.
  (c) open sensitive field a schema carrying a non-false `x-sensitive` (anywhere: components, inline, items, allOf)
                           carries none of maxLength, pattern, enum, format, minimum, maximum. The green line counts them.
  (d) unbound decision     in `design.md § Decision History`, a `Decision | Law | Gate | Record` row with no gate, a gate the
                           project does not run (a profile member that is not framework-only, or a `verification.gates` row),
                           no law or one the governance index does not have (`new` = the law its Record's ADR adds), a
                           Record with no file under docs/project_log/adr/, a REPLACE record aimed at another law; or an ADR
                           named there that adds or replaces a law and is the Record of no row (prose only). A `{{…}}` cell is
                           blank. No row and no law-making ADR → `n/a` with its reason.
  (e) unnamed reference    (EVOL-132) a changed decision artefact — `docs/spec/<ID>/**.md|.feature`, `docs/project_log/adr/*.md`,
                           `docs/ux/vision/*.md`, in the repo or in its External home (a pin) — cites
                           ``Reference product: `Name` · <source>`` (bold label allowed; outside code fences) naming a product
                           the answer `docs/setup.md → reference_products` does not name (case-insensitive; a carried Q13
                           answer counts; «first of its kind» names none), or with no source after `·`; an unreadable answer
                           home is red. A file with no citation is not judged by this clause.
An unparseable, empty or malformed contract is red with its reason (LAW-08). Nothing to judge → `freeze: n/a`.
Raised ⊆ declared belongs to the one contract reader, gates/contracts.py (`--parity`, the loop member contract-parity, EVOL-070) — not this one.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

from . import corpus, documents, profile
from .branch import FEATURE_ID
from .common import GateFault, clean as _clean, key, parse_yaml, read_frontmatter, unfenced as _unfenced
from .digests import changed_paths
from .seal import DEFAULT_SEAL_DIR, RED, _norm_path, vcfg

DESIGN_RE = re.compile(r"docs/spec/[^/]+/design\.md")
DECISION_RE = re.compile(r"docs/spec/[^/]+/.+\.(?:md|feature)|docs/project_log/adr/[^/]+\.md|docs/ux/vision/[^/]+\.md")   # EVOL-132: where a decision cites
CITE = re.compile(r"(?<![\w`-])(?:\*\*)?Reference product:(?:\*\*)?[ \t]+((?:`[^`\n]+`[ \t]*,?[ \t]*)+)([^\n]*)")
CONTRACT_RE = re.compile(r"contracts/openapi/.+\.(?:ya?ml|json)")
METHODS = ("get", "put", "post", "delete", "patch", "head", "options")
CONSTRAINTS = ("maxLength", "pattern", "enum", "format", "minimum", "maximum")
WEIGHTS = ("security", "availability", "both", "none")   # closed (owner RDR «1»): any other word is red
WEIGHTED = ("security", "availability", "both")
BLANK = re.compile(r"^(?:|—|-|–|tbd|todo|\?+|\{\{[^}]*\}\})$", re.I)
DECISION_COLUMNS = ("decision", "law", "gate", "record")
ADR_ID = re.compile(rf"(?<![\w-])ADR-(?:{FEATURE_ID}-)?\d{{1,12}}(?!\w)")   # `ADR-7`, a feature's own `ADR-FEAT-009-1` (EVOL-134), and either in a file name `ADR-7-slug.md`
LAW_ID = re.compile(r"P?LAW-\d{2}")
ADR_DIR = "docs/project_log/adr"
LAW_MAKING = ("ADD", "REPLACE")
GATE_HINT = ("a gate the project runs: a profile member that is not framework-only (`gate.py profile --json`, any profile) "
             "or a verification-loop row (`config/quality.json → verification.gates`), never the built-in `red`")


def _cells(line: str) -> list[str]:
    return [c.strip() for c in line.strip().strip("|").split("|")]


def _section(text: str, title: str) -> str:
    m = re.search(rf"(?mi)^##\s+{re.escape(title)}\s*$", text or "")
    if not m:
        return ""
    end = re.search(r"(?m)^##\s", text[m.end():])
    return text[m.end(): m.end() + end.start()] if end else text[m.end():]


def _blank(s: str) -> bool:
    return bool(BLANK.match(s.strip().strip("`*_ ").strip()))


def questions(text: str) -> tuple[list[str], int, str]:
    """Clause (a) on one design: (problems, weighted rows judged, why nothing was judged)."""
    if not re.search(r"(?mi)^##\s+Reliability Questions\s*$", text or ""):
        return [], 0, "no `## Reliability Questions` section — nothing to judge"
    problems, header, judged, seen_set = [], None, 0, False
    for line in _section(text, "Reliability Questions").splitlines():
        if not line.strip().startswith("|"):
            header = None
            continue
        cells = _cells(line)
        if header is None:
            header = [c.lower() for c in cells]
            continue
        if all(set(c) <= set(":- ") for c in cells):
            continue
        if "weight" not in header or not any(h.startswith("rq-") for h in header):
            continue   # the mapping table, or any table that is not the question set
        seen_set = True
        row = dict(zip(header, cells))
        cap = row.get(header[0], "?")
        weight = row.get("weight", "").strip().strip("`*_ ").strip().lower()
        if weight not in WEIGHTS:
            problems.append(f"capability `{cap}` carries weight `{row.get('weight', '')}` — the weight is one of {', '.join(WEIGHTS)}")
            continue
        if weight not in WEIGHTED:
            continue
        judged += 1
        for h in header:
            if not h.startswith("rq-"):
                continue
            answer, _, source = row.get(h, "").partition("·")
            if _blank(answer) or _blank(source):
                problems.append(f"capability `{cap}` ({row['weight']}) leaves {h.upper()} without "
                                f"{'an answer' if _blank(answer) else 'a source'} — answer it with a cited source before the freeze")
    if not seen_set:
        return problems, 0, "no question table with a `Weight` and `RQ-…` header under `## Reliability Questions` — nothing to judge"
    return problems, judged, "" if judged else "no capability weighted security, availability or both — nothing to judge"


def _fold(s: str) -> str:
    return " ".join(str(s).split()).lower()


def citations(text: str, named) -> tuple[list[str], int]:
    """Clause (e) on one decision artefact: (problems, citations judged). `named` — the answer's product names (a set,
    folded), or a str: why the answer home cannot be read (every citation is then red with it)."""
    problems, n = [], 0
    for m in CITE.finditer(_unfenced(text)):
        rest = m.group(2)
        source = rest.split("·", 1)[1] if "·" in rest else ""
        for name in re.findall(r"`([^`\n]+)`", m.group(1)):
            n += 1
            if isinstance(named, str):
                problems.append(f"cites `{name}` as a reference product, but {named}")
            elif _fold(name) not in named:
                problems.append(f"cites `{name}` as a reference product — the answer (`docs/setup.md → reference_products`) does not name it; "
                                f"cite one it names, or the person adds it at SETUP (Q2.1)")
        if _blank(source):
            problems.append(f"cites {m.group(1).strip()} with no official source — write ``Reference product: `Name` · <its source>``")
    return problems, n


def _named(repo: Path):
    """The folded product names of the answer, carry included; a str (the reason) when the answer home cannot be read."""
    from . import discovery
    home = repo / discovery.SETUP_MD
    if not home.is_file():
        return f"the answer home {discovery.SETUP_MD} is absent — SETUP writes it; the citation cannot be held to the person's answer"
    try:
        ans = discovery.flatten(read_frontmatter(home))
        if (repo / discovery.REGISTRY).is_file():   # the carry lives in the registry; at CI `.context/` is not on the runner
            ans = discovery._carry(discovery.load_registry(repo), ans)
    except GateFault as e:
        return f"the answer home cannot be read ({e})"
    refs = ans.get("reference_products")
    return {_fold(e["name"]) for e in refs or [] if isinstance(e, dict) and isinstance(e.get("name"), str) and e["name"].strip()} \
        if isinstance(refs, list) else set()


def _plain(s: str) -> str:
    return s.strip().strip("`*_ ").strip()


def _gates(repo: Path) -> set[str]:
    """The gates a project runs: every profile member that is not framework-only, and its verification-loop rows."""
    try:
        names = {m[0] for m in profile.members(repo) if not m[5]}
    except GateFault:
        names = {m[0] for m in profile.MEMBERS if not m[5]}   # a malformed project key is the profile's red, never this gate's
    try:
        names |= {g for g in vcfg(repo)["gates"] if g != RED}
    except GateFault:
        pass   # no loop declared: the profile members only
    return names


def _adr(repo: Path, rid: str) -> dict | None:
    """The frontmatter of the project ADR `rid` (`ADR-N.md` or `ADR-N-slug.md`); None when no file carries it."""
    d = repo / ADR_DIR
    hits = (sorted(d.glob(f"{rid}.md")) + sorted(d.glob(f"{rid}-*.md"))) if d.is_dir() else []
    return read_frontmatter(hits[0]) if hits else None


def _read_adr(repo: Path, rid: str, problems: list[str]) -> dict | None:
    """`_adr`, with a frontmatter that does not parse reported red on the ADR it names — never a fault that hides the verdict."""
    try:
        return _adr(repo, rid)
    except GateFault as e:
        problems.append(f"{rid}: its frontmatter does not read ({str(e).splitlines()[0][:160]}) — fix the ADR file")
        return None


def _kind(fm: dict | None) -> str:
    return str((fm or {}).get("amendment_kind") or "").strip().upper()


def decisions(repo: Path, text: str) -> tuple[list[str], int, str]:
    """Clause (d) on one design: (problems, decisions judged, why nothing was judged)."""
    sect = _section(text, "Decision History (ADR)") or _section(text, "Decision History")
    rows, header, named, near, sep = [], None, set(), set(), False
    for line in sect.splitlines():
        if not line.strip().startswith("|"):
            header = None
            named |= set(ADR_ID.findall(line))
            continue
        cells = _cells(line)
        if header is None:
            header, sep = [_plain(c).lower() for c in cells], True
            continue
        if sep and all(set(c) <= set(":- ") for c in cells) and any("-" in c for c in cells):
            sep = False   # the separator is the line right after the header; any later line is a row
            continue
        sep = False
        cols = [h for h in DECISION_COLUMNS if h in header]
        if len(cols) < len(DECISION_COLUMNS):
            named |= set(ADR_ID.findall(line))   # another table: its ADR names count as prose for this clause
            if "decision" in cols and len(cols) >= 2 and ({"law", "gate"} & set(cols)):
                near.add(", ".join(f"`{h.capitalize()}`" for h in DECISION_COLUMNS if h not in cols))
            continue
        row = dict(zip(header, cells))
        named |= set(ADR_ID.findall(" ".join(v for k, v in row.items() if k != "record")))   # an ADR cited in the row's text
        rows.append(row)
    problems, recorded = [f"a decision table lacks the column(s) {m} — a decision table carries `Decision | Law | Gate | Record`"
                          for m in sorted(near)], set()
    laws = {law["id"] for part in corpus.laws(repo).values() for law in part} if rows else set()
    gates = _gates(repo) if rows else set()
    for row in rows:
        dec, law, rec = row.get("decision", ""), _plain(row.get("law", "")), _plain(row.get("record", ""))
        gate = "" if _blank(row.get("gate", "")) else _plain(row.get("gate", "").partition("·")[0])
        name = f"critical decision `{_plain(dec)}`"
        if _blank(dec):
            problems.append("a critical decision row names no decision — say what was decided")
            name = "a critical decision row"
        elif any("{{" in v for v in row.values()):
            problems.append(f"{name} still carries a template placeholder (`{{{{…}}}}`) — fill it from docs/setup.md or drop the row")
        fm = None
        if not _blank(rec):
            if not ADR_ID.fullmatch(rec):
                problems.append(f"{name}: record `{rec}` is not an ADR id — name the ADR (`ADR-N`, or a feature's own, `ADR-FEAT-009-1`) that records it")
            else:
                recorded.add(rec)
                fm = _read_adr(repo, rec, problems)
                if fm is None:
                    problems.append(f"{name}: record `{rec}` has no readable file under {ADR_DIR}/ — write the ADR or name the right one")
        if _blank(law):
            problems.append(f"{name} names no law — name the law it applies (`LAW-NN` / `PLAW-NN`) or `new` with the ADR that adds it")
        elif law.lower() == "new":
            if _blank(rec):
                problems.append(f"{name}: a `new` law needs the record of the ADR that adds it")
            elif fm is not None and _kind(fm) != "ADD":
                problems.append(f"{name}: record `{rec}` does not add a law (amendment_kind `{_kind(fm) or 'none'}`) — name the law it applies, or record the ADR that adds it")
        elif not (LAW_ID.fullmatch(law) and law in laws):
            problems.append(f"{name} names law `{law}`, which the governance index does not have — name a law `gate.py laws` lists, or `new`")
        elif fm is not None and _kind(fm) == "REPLACE":
            target = LAW_ID.search(str(fm.get("target_section") or ""))
            if target and target.group(0) != law:
                problems.append(f"{name}: {rec} replaces {target.group(0)}, not {law} — name the law the record replaces")
        if _blank(gate):
            problems.append(f"{name} names no gate — name the gate that checks it: {GATE_HINT}")
        elif gate not in gates:
            problems.append(f"{name} names gate `{gate}`, which the project does not run — name {GATE_HINT}")
    for rid in sorted(named - recorded):
        kind = _kind(_read_adr(repo, rid, problems))
        if kind in LAW_MAKING:
            problems.append(f"{rid} {'adds' if kind == 'ADD' else 'replaces'} a law and is recorded as prose only — "
                            f"give it a `Decision | Law | Gate | Record` row with its law and the gate that checks it")
    if rows or problems:
        return problems, len(rows), ""
    return problems, 0, "no critical decision (no `Decision | Law | Gate | Record` row, no ADR that adds or replaces a law) — nothing to judge"


MAX_DEPTH = 200


def _walk(node, ptr: str = "#"):
    """Every mapping of the document, each object once (a YAML alias is walked once), iteratively (no recursion limit)."""
    seen, todo = set(), [(node, ptr, 0)]
    while todo:
        n, p, d = todo.pop()
        if not isinstance(n, (dict, list)) or id(n) in seen:
            continue
        if d > MAX_DEPTH:
            raise GateFault(f"the contract is nested deeper than {MAX_DEPTH} levels at {p[:120]}… — flatten it with `$ref`")
        seen.add(id(n))
        kids = n.items() if isinstance(n, dict) else enumerate(n)
        if isinstance(n, dict):
            yield p, n
        todo += [(v, f"{p}/{k}", d + 1) for k, v in reversed(list(kids))
                 if isinstance(v, (dict, list)) and id(v) not in seen]   # scalars carry no pointer: no string per leaf


def _sensitive(v) -> bool:
    """Any marker that is not false marks the field (`true`, `"true"`, `1`); `false`, `"false"`, `0`, `""` do not.
    Decided by type, never by `str()`: a stringified aliased list re-expands every alias."""
    if isinstance(v, bool) or v is None:
        return bool(v)
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        return v.strip().lower() not in ("false", "0", "", "no", "off")
    return bool(v)


def contract(doc, outage: str, counted: list | None = None) -> list[str]:
    """Clauses (b) and (c) on one parsed OpenAPI document; `counted` receives the number of sensitive fields."""
    problems = []
    if doc is None or doc == {} or doc == "":
        return ["empty contract — nothing in it declares an operation; write the contract or drop the file"]
    if not isinstance(doc, dict):
        return ["the contract is not a mapping — not an OpenAPI document"]
    paths = doc.get("paths") or {}
    if not isinstance(paths, dict):
        raise GateFault("its `paths` is not a mapping of routes — not an OpenAPI document")
    for path, item in paths.items():
        if not isinstance(item, dict):
            continue
        for meth in METHODS:
            op = item.get(meth)
            if not isinstance(op, dict):
                continue
            responses = op.get("responses") or {}
            if not isinstance(responses, dict):
                raise GateFault(f"{meth.upper()} {path}: its `responses` is not a mapping of statuses — not an OpenAPI document")
            if outage not in {str(k).strip("'\"") for k in responses}:   # the subset parser keeps a key's quotes
                problems.append(f"{meth.upper()} {path} declares no `{outage}` response — say what it returns when a dependency is down")
    marked = 0
    for ptr, node in _walk(doc, "#"):
        if _sensitive(node.get("x-sensitive")):
            marked += 1
            if not any(c in node for c in CONSTRAINTS):
                problems.append(f"sensitive field {ptr} carries no constraint ({', '.join(CONSTRAINTS)}) — bound its input")
    if counted is not None:
        counted.append(marked)
    return problems


def _load(path: Path):
    return _parse(path.read_text(encoding="utf-8", errors="replace"), path.suffix)


def _parse(text: str, suffix: str):
    """A contract's text as data — `.json` by JSON, anything else by YAML (a file on disk, or one read at a ref)."""
    if suffix == ".json":
        try:
            return json.loads(text)
        except ValueError as e:
            raise GateFault(f"not valid JSON ({e})") from None
    if not text.strip():
        return None
    try:
        return parse_yaml(text)
    except GateFault as e:
        try:
            import yaml  # type: ignore  # noqa: F401
        except ImportError:
            raise GateFault(f"{e} — install PyYAML: the subset parser cannot read lists of mappings") from None
        raise
    except (RecursionError, ValueError, OverflowError) as e:
        raise GateFault(f"not readable YAML ({type(e).__name__})") from None


def check(repo: Path, base: str, branch: str | None = None) -> dict:
    try:
        cfg = vcfg(repo)
    except GateFault:
        cfg = {"dir": DEFAULT_SEAL_DIR}
    moved = {_norm_path(c) for c in changed_paths(repo, base, cfg)}
    changed = sorted(c for c in moved if (repo / c).is_file())
    # a changed pin is a changed design (EVOL-080): the artefact in its home, read through the one reader
    designs = sorted({c for c in documents.artefacts(sorted(moved)) if DESIGN_RE.fullmatch(c) and documents.exists(repo, c)})
    contracts = [c for c in changed if CONTRACT_RE.fullmatch(c)]
    rows, unread = [], documents.Outage()
    named = None   # read once, only when a citation needs it
    def cite(text: str):
        nonlocal named
        if not CITE.search(text or "") or not CITE.search(_unfenced(text)):
            return [], 0
        if named is None:
            named = _named(repo)
        return citations(text, named)
    for d in designs:
        disk = repo / d
        try:
            text = disk.read_text(encoding="utf-8", errors="replace") if disk.is_file() else documents.text(repo, d)
        except documents.StoreDown as e:
            unread.note(e); continue   # unjudged: settled below, never a lost red
        except GateFault as e:   # a pin the store does not honour is red, never infra
            rows.append({"id": d, "ok": False, "problems": [str(e)], "note": "the pinned design could not be read"}); continue
        problems, judged, why = questions(text or "")
        d_problems, d_judged, d_why = decisions(repo, text or "")
        c_problems, c_judged = cite(text or "")
        parts = ([f"{judged} weighted capabilit{'y' if judged == 1 else 'ies'} answered with a cited source"] if judged else []) + \
                ([f"{d_judged} critical decision{'' if d_judged == 1 else 's'} bound to a law and a gate"] if d_judged else []) + \
                ([f"{c_judged} reference citation{'' if c_judged == 1 else 's'} named in the answer"] if c_judged else [])
        problems += d_problems + c_problems
        note = "; ".join(parts) if parts else f"n/a — {'; '.join(w for w in (why, d_why) if w)}"
        rows.append({"id": d, "ok": not problems, "problems": problems, "note": note, "na": not parts and not problems})
    # every other decision artefact, in the repo or in its External home (EVOL-080): read through the one reader
    for f in (a for a in documents.artefacts(sorted(moved)) if DECISION_RE.fullmatch(a) and not DESIGN_RE.fullmatch(a) and documents.exists(repo, a)):
        disk = repo / f
        try:
            text = disk.read_text(encoding="utf-8", errors="replace") if disk.is_file() else documents.text(repo, f)
        except documents.StoreDown as e:
            unread.note(e); continue
        except GateFault as e:
            rows.append({"id": f, "ok": False, "problems": [str(e)], "note": "the pinned artefact could not be read"}); continue
        c_problems, c_judged = cite(text or "")
        if c_judged:
            rows.append({"id": f, "ok": not c_problems, "problems": c_problems,
                         "note": f"{c_judged} reference citation{'' if c_judged == 1 else 's'} named in the answer"})
    if contracts:
        try:
            outage = str(key(repo, "contracts.outage_status", required=True))
        except GateFault as e:
            return {"ok": False, "files": designs + contracts, "entries": [], "reason": str(e)}
        for c in contracts:
            counted: list = []
            try:
                problems = contract(_load(repo / c), outage, counted)
            except RecursionError:
                problems = ["cannot be read as a contract — nested too deep for the reader; flatten it with `$ref` so the freeze can judge it"]
            except GateFault as e:
                problems = [f"cannot be read as a contract — {str(e).replace('frontmatter is not valid YAML', 'not valid YAML')}; fix its syntax so the freeze can judge it"]
            n = counted[0] if counted else 0
            rows.append({"id": c, "ok": not problems, "problems": problems,
                         "note": f"every operation declares `{outage}`; {n} sensitive field{'' if n == 1 else 's'} bounded"})
    unread.settle([r for r in rows if not r["ok"]])
    if not rows:
        return {"ok": True, "files": [], "entries": [], "reason": "no design (docs/spec/*/design.md), no contract (contracts/openapi/**) and no reference citation in the change — nothing to judge"}
    red = [r for r in rows if not r["ok"]]
    if all(r.get("na") for r in rows):   # nothing judged: n/a with its reason, never the ok note (ADR-EVOL-115 Decision 3)
        return {"ok": True, "na": True, "files": designs, "entries": rows,
                "reason": "nothing judged — " + "; ".join(r["note"][len("n/a — "):] for r in rows)}
    return {"ok": not red, "files": designs + contracts, "entries": rows,
            "reason": f"{len(red)} of {len(rows)} file(s) red" if red else f"{len(rows)} file(s) green — reliability planned up front, critical decisions bound"}


def render(res: dict) -> str:
    if not res.get("entries"):
        return _clean(f"freeze: {'n/a' if res['ok'] else 'RED'} — {res['reason']}")
    lines = [f"freeze: {'n/a' if res.get('na') else 'ok' if res['ok'] else 'RED'} — {res['reason']}"]
    for r in res["entries"]:
        if r["ok"]:
            lines.append(f"  ✓ {r['id']}: {r['note']}")
        else:
            lines += [f"  ✗ {r['id']}: {p}" for p in r["problems"]]
    return "\n".join(_clean(ln) for ln in lines)
